insert into public.sq_lorekeeper (term_id, is_active, grade_level, passage, question, choice_a, choice_b, choice_c, choice_d, correct_choice) values
  (1, true, 4, NULL, 'Which of these is an example of a mixture that is a solution?', 'Trail mix with nuts and raisins', 'Lemonade (sugar and lemon juice dissolved in water)', 'A bowl of cereal with milk poured on top', 'Sand mixed with gravel', 'b'),
  (1, true, 4, NULL, 'Which of these best describes the texture of a material?', 'How it feels when you touch it, like rough or smooth', 'How much it weighs', 'Its exact color', 'How much space it takes up', 'a'),
  (1, true, 4, NULL, 'Which of these changes is reversible, showing it is a physical change?', 'Wood burning into ash', 'Ice melting into water', 'An egg cooking', 'Iron rusting', 'b'),
  (1, true, 4, NULL, 'A magnet''s push away from another magnet is called', 'Attraction', 'Repulsion', 'Friction', 'Gravity', 'b'),
  (1, true, 4, NULL, 'A magnet''s pull toward another magnet or metal object is called', 'Repulsion', 'Attraction', 'Friction', 'Tension', 'b'),
  (1, true, 4, NULL, 'Which of these forces pulls all objects toward the center of the Earth?', 'Friction', 'Magnetism', 'Gravity', 'Tension', 'c'),
  (1, true, 4, NULL, 'If a runner covers 400 meters in 100 seconds, what is their speed?', '4 meters per second', '40 meters per second', '400 meters per second', '100 meters per second', 'a'),
  (1, true, 4, NULL, 'Which of these would slow down a rolling ball the fastest?', 'Rolling on smooth ice', 'Rolling on rough grass', 'Rolling on polished tile', 'Rolling on a smooth wooden floor', 'b'),
  (1, true, 4, NULL, 'Which of these best explains why wearing rubber-soled shoes helps prevent slipping?', 'Rubber creates more friction with the ground than smooth materials', 'Rubber removes all friction', 'Rubber is magnetic', 'Rubber has no effect on grip', 'a'),
  (1, true, 4, NULL, 'Sound energy is produced by', 'Vibrations', 'Light waves', 'Magnetic fields', 'Gravity alone', 'a'),
  (1, true, 4, NULL, 'Which of these is an example of light energy being converted to another form?', 'A solar panel converting sunlight into electricity', 'A fan blowing air', 'A magnet attracting iron', 'Water freezing into ice', 'a'),
  (1, true, 4, NULL, 'Which material would be the best conductor of heat?', 'Wood', 'Metal spoon', 'Plastic', 'Rubber', 'b'),
  (1, true, 4, NULL, 'Which material would be the best insulator to keep a drink cold?', 'A metal cup with no cover', 'A foam or plastic insulated cup', 'An open glass', 'A thin aluminum can left in the sun', 'b'),
  (1, true, 4, NULL, 'Why can you see a rainbow when sunlight passes through raindrops?', 'The light is absorbed completely', 'The light is refracted and separated into different colors', 'The light disappears', 'The raindrops create their own light', 'b'),
  (1, true, 4, NULL, 'A guitar string vibrating faster produces a sound with a', 'Lower pitch', 'Higher pitch', 'No sound at all', 'Change in color', 'b'),
  (1, true, 4, NULL, 'Which of these best explains why we hear an echo in a large empty room but not in a room full of soft furniture?', 'Hard, empty surfaces reflect sound waves back, while soft materials absorb them', 'Furniture creates more sound', 'Empty rooms have no sound waves', 'Soft materials reflect sound better than hard surfaces', 'a'),
  (1, true, 4, 'In a coral reef ecosystem, algae and coral use sunlight to produce food. Small fish eat the algae. Larger fish eat the small fish. When any of these organisms die, decomposers break them down.', 'In this ecosystem, what role does the algae play?', 'Producer', 'Primary consumer', 'Secondary consumer', 'Decomposer', 'a'),
  (1, true, 4, 'In a coral reef ecosystem, algae and coral use sunlight to produce food. Small fish eat the algae. Larger fish eat the small fish. When any of these organisms die, decomposers break them down.', 'What role do the larger fish play in this ecosystem?', 'Producer', 'Primary consumer', 'Secondary consumer', 'Decomposer', 'c'),
  (1, true, 4, NULL, 'A cactus storing water in its thick stem is an adaptation for surviving in what kind of environment?', 'A rainforest', 'A desert', 'An ocean', 'A tundra', 'b'),
  (1, true, 4, NULL, 'A fish''s gills are an adaptation that allows it to', 'Breathe underwater', 'Fly through the air', 'Change colors', 'Dig burrows', 'a'),
  (1, true, 4, NULL, 'If all the decomposers in an ecosystem disappeared, what would most likely happen?', 'Dead plants and animals would build up and nutrients would not return to the soil', 'Nothing would change at all', 'Producers would multiply endlessly', 'All consumers would become producers', 'a'),
  (1, true, 4, NULL, 'Which of these best describes a food web compared to a food chain?', 'A food web shows only one path of energy, like a food chain', 'A food web connects many overlapping food chains together', 'A food web has no producers', 'A food web only includes decomposers', 'b'),
  (1, true, 4, 'Before the Spanish colonized the Philippines, early Filipino communities already had organized systems of trade, writing, and governance. Datus led barangays, and many communities traded with neighboring kingdoms in Southeast Asia.', 'According to the passage, what systems did early Filipino communities already have before Spanish colonization?', 'Trade, writing, and governance', 'Airplanes and cars', 'Modern schools only', 'None at all', 'a'),
  (1, true, 4, NULL, 'Which of these best describes the significance of pre-colonial Philippine trading kingdoms?', 'They show that early Filipinos had organized societies and international trade connections', 'They prove the Philippines had no civilization before Spain arrived', 'They were unrelated to any other kingdoms in the region', 'They only existed after Spanish colonization', 'a'),
  (1, true, 4, NULL, 'The Visayas island group is located', 'North of Luzon', 'Between Luzon and Mindanao', 'South of Mindanao', 'Outside the Philippines', 'b'),
  (1, true, 4, NULL, 'Which of these is a major body of water located between Luzon and the Asian mainland?', 'The Pacific Ocean', 'The South China Sea', 'The Atlantic Ocean', 'The Indian Ocean', 'b'),
  (1, true, 4, NULL, 'The Cordillera mountain range is best known for its', 'Rice terraces built by the Ifugao people', 'Coral reefs', 'Volcanic beaches', 'Underground rivers only', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why the Philippines has many active volcanoes?', 'It is located along the Pacific Ring of Fire', 'It has no tectonic activity', 'It is far from any fault lines', 'Volcanoes only exist in cold climates', 'a'),
  (1, true, 4, NULL, 'Luzon is the location of which of these?', 'Manila, the capital of the Philippines', 'Davao City only', 'Cebu City only', 'No major cities', 'a'),
  (1, true, 4, NULL, 'Which of these countries, an ASEAN member, is Singapore known for being?', 'A large agricultural country', 'A small but highly developed city-state', 'A country without any government', 'A country outside Southeast Asia', 'b'),
  (1, true, 4, NULL, 'The capital of Thailand, an ASEAN member country, is', 'Bangkok', 'Hanoi', 'Manila', 'Phnom Penh', 'a'),
  (1, true, 4, NULL, 'The capital of Vietnam, an ASEAN member country, is', 'Hanoi', 'Bangkok', 'Jakarta', 'Vientiane', 'a'),
  (1, true, 4, NULL, 'Which of these is one benefit of the Philippines being part of ASEAN?', 'Easier trade and cooperation with neighboring Southeast Asian countries', 'Losing all trade partners', 'Being cut off from the region', 'Having no say in regional decisions', 'a'),
  (1, true, 4, NULL, 'ASEAN was formed mainly to promote regional', 'Peace, stability, and economic cooperation', 'War between neighboring countries', 'Isolation from world trade', 'Division among Southeast Asian nations', 'a'),
  (1, true, 4, NULL, 'Gold and copper found underground in the Philippines are examples of', 'Mineral resources', 'Marine resources', 'Agricultural resources', 'Forest resources', 'a'),
  (1, true, 4, NULL, 'Coconuts, rice, and sugarcane grown on farms are examples of', 'Mineral resources', 'Agricultural resources', 'Marine resources only', 'Forest resources only', 'b'),
  (1, true, 4, NULL, 'Which of these actions supports the sustainable use of forest resources?', 'Cutting down all the trees in a forest at once', 'Replanting trees after harvesting some for lumber', 'Burning forests for farmland without planning', 'Ignoring forest conservation laws', 'b'),
  (1, true, 4, NULL, 'Overfishing in coastal waters can lead to', 'An unlimited supply of fish forever', 'A decline in fish populations over time', 'More fish appearing instantly', 'No effect on the ecosystem', 'b'),
  (1, true, 4, NULL, 'Which of these best shows a sustainable fishing practice?', 'Using nets that catch only mature fish, allowing young fish to grow', 'Catching every fish possible with no limits', 'Using explosives to catch fish', 'Fishing in protected marine sanctuaries', 'a'),
  (1, true, 4, NULL, 'A factory that turns raw sugarcane into refined sugar is engaged in what economic activity?', 'Farming', 'Manufacturing', 'Mining', 'Fishing', 'b'),
  (1, true, 4, NULL, 'Exporting Philippine mangoes to other countries is an example of', 'Farming only', 'International trade', 'Mining', 'Manufacturing only', 'b'),
  (1, true, 4, NULL, 'Which of these economic activities would most likely take place in a mountainous, mineral-rich region?', 'Mining', 'Deep-sea fishing', 'Coastal tourism only', 'Rice farming in a river delta', 'a'),
  (1, true, 4, NULL, 'A story about a girl who discovers a hidden treasure map and goes on an adventure is what text type?', 'Narrative', 'Expository', 'Persuasive only', 'A dictionary entry', 'a'),
  (1, true, 4, NULL, 'A paragraph explaining the steps of the water cycle with facts and diagrams is what text type?', 'Narrative', 'Descriptive', 'Expository', 'Persuasive', 'c'),
  (1, true, 4, NULL, 'An advertisement trying to convince people to buy a new toy is what text type?', 'Narrative', 'Persuasive', 'Expository only', 'Descriptive only', 'b'),
  (1, true, 4, 'Every afternoon, Lola Rosa waters her garden, hums a happy tune, and smiles at her flowers. Her neighbors often stop by just to admire how vibrant and colorful her garden looks compared to others on the street.', 'What can you conclude about Lola Rosa based on the passage?', 'She dislikes gardening', 'She takes great care of and enjoys her garden', 'She never waters her plants', 'Her garden is the least colorful on the street', 'b'),
  (1, true, 4, NULL, 'Which of these best shows the difference between drawing a conclusion and making an inference?', 'They are the same thing; both use text clues and prior knowledge to figure something out', 'A conclusion never uses text evidence', 'An inference is always stated directly in the text', 'There is no relationship between them', 'a'),
  (1, true, 4, NULL, 'An author who writes an editorial arguing that schools need more books has what purpose?', 'To entertain', 'To persuade', 'To describe only', 'To confuse', 'b'),
  (1, true, 4, NULL, 'Which of these sentences states a FACT?', 'The Earth orbits the Sun.', 'Winter is the best season.', 'Chocolate ice cream tastes better than vanilla.', 'Cats make better pets than dogs.', 'a'),
  (1, true, 4, NULL, 'Which of these sentences states an OPINION?', 'A week has seven days.', 'Reading books is more fun than watching TV.', 'The Philippines has 17 regions.', 'Water is made of hydrogen and oxygen.', 'b'),
  (1, true, 4, NULL, 'In the sentence "The wind whispered through the trees," which figure of speech is used?', 'Personification', 'Simile', 'Hyperbole', 'Onomatopoeia', 'a'),
  (1, true, 4, NULL, 'In the sentence "His backpack was as heavy as a boulder," which figure of speech is used?', 'Metaphor', 'Simile', 'Personification', 'Onomatopoeia', 'b'),
  (1, true, 4, NULL, 'In the sentence "The snow was a white blanket over the town," which figure of speech is used?', 'Simile', 'Metaphor', 'Onomatopoeia', 'Hyperbole', 'b'),
  (1, true, 4, NULL, 'In the sentence "I''m so hungry I could eat a whole cow," which figure of speech is used?', 'Hyperbole', 'Simile', 'Personification', 'Onomatopoeia', 'a'),
  (1, true, 4, NULL, 'In the sentence "The thunder boomed and crashed overhead," which figure of speech is used?', 'Onomatopoeia', 'Simile', 'Metaphor', 'Personification', 'a'),
  (1, true, 4, NULL, 'Which sentence uses a subordinate clause correctly to add extra information?', 'Although it was late, we finished our homework.', 'Although it was late we, finished our homework.', 'It was late, although we finished, our homework.', 'We finished, although, our homework it was late.', 'a'),
  (1, true, 4, NULL, 'Which sentence correctly uses the relative pronoun "whose"?', 'The boy whose backpack was lost found it later.', 'The boy which backpack was lost found it later.', 'The boy who backpack was lost found it later.', 'The boy whom backpack was lost found it later.', 'a'),
  (1, true, 4, NULL, 'Which sentence correctly uses the past perfect tense?', 'She had already left when I arrived.', 'She has already left when I arrived.', 'She already leave when I arrived.', 'She will already left when I arrive.', 'a'),
  (1, true, 4, NULL, 'Which of these sentences is written in the passive voice?', 'The teacher graded the tests.', 'The tests were graded by the teacher.', 'The teacher is grading the tests.', 'The teacher will grade the tests.', 'b'),
  (1, true, 4, NULL, 'The prefix "mis-" in the word "misunderstand" means', 'To understand correctly', 'Wrongly or incorrectly', 'To understand again', 'Never to understand', 'b'),
  (1, true, 4, NULL, 'The suffix "-tion" in the word "education" changes the verb "educate" into what part of speech?', 'A noun', 'A verb', 'An adjective', 'An adverb', 'a'),
  (1, true, 4, NULL, 'Which word has a more negative connotation than "confident"?', 'Assured', 'Arrogant', 'Self-assured', 'Secure', 'b'),
  (1, true, 4, NULL, 'Which word has a more positive connotation for someone who speaks their mind?', 'Blunt', 'Rude', 'Candid', 'Harsh', 'c'),
  (1, true, 4, NULL, 'Which word is a synonym for "exhausted"?', 'Energetic', 'Drained', 'Lively', 'Refreshed', 'b'),
  (1, true, 4, NULL, 'Which word is an antonym for "ancient"?', 'Old', 'Modern', 'Historic', 'Antique', 'b'),
  (1, true, 4, NULL, 'Ang uring tekstong naglalahad ng pananaw at nagsusumikap na kumbinsihin ang mambabasa ay tinatawag na', 'Salaysay', 'Persuasibo', 'Nagbibigay-impormasyon', 'Paglalarawang-salita', 'b'),
  (1, true, 4, NULL, 'Sa pangungusap na "Ang ulan ay umiiyak sa bintana," anong tayutay ang ginamit?', 'Simili', 'Personipikasyon', 'Pagmamalabis', 'Onomatopeya', 'b'),
  (1, true, 4, NULL, 'Sa pangungusap na "Kasing tapang niya ng leon," anong tayutay ang ginamit?', 'Simili', 'Metapora', 'Personipikasyon', 'Pagmamalabis', 'a'),
  (1, true, 4, NULL, 'Ang salitang "kulog" na tumutukoy sa tunog ng kidlat ay halimbawa ng anong tayutay?', 'Simili', 'Metapora', 'Onomatopeya', 'Personipikasyon', 'c'),
  (1, true, 4, NULL, 'Ang epikong "Ibalon" ay isang halimbawa ng panitikang naglalarawan ng', 'Kabayanihan at pakikipagsapalaran ng isang bida', 'Balita sa telebisyon', 'Isang aklat-aralin sa agham', 'Talaan ng mga numero', 'a'),
  (1, true, 4, NULL, 'Sa isang pabula, karaniwang mga hayop ang tauhan upang', 'Magturo ng aral sa mas madaling paraan', 'Magbigay ng balita', 'Magturo ng matematika', 'Magbilang ng oras', 'a'),
  (1, true, 4, NULL, 'Alin sa mga sumusunod ang pangngalang pantangi?', 'Bata', 'Lungsod', 'Maynila', 'Bahay', 'c'),
  (1, true, 4, NULL, 'Alin sa mga sumusunod ang pandiwang nasa hinaharap na panahon (future tense)?', 'Kumain', 'Kumakain', 'Kakain', 'Kinain', 'c'),
  (1, true, 4, NULL, 'Alin sa mga sumusunod ang pandiwang nasa nakaraang panahon (past tense)?', 'Kakain', 'Kumakain', 'Kumain', 'Kakainin', 'c'),
  (1, true, 4, NULL, 'Sa pangungusap na "Ang batang matalino ay nag-aral nang mabuti," alin ang pang-uri?', 'Bata', 'Matalino', 'Nag-aral', 'Mabuti', 'b'),
  (1, true, 4, NULL, 'Ang paksang pangungusap ay dapat matagpuan kadalasan sa', 'Gitna ng talata lamang', 'Simula ng talata', 'Wakas ng talata lamang', 'Alinmang bahagi na walang pattern', 'b'),
  (1, true, 4, NULL, 'Ang mga detalyeng sumusuporta sa isang talata ay dapat', 'Walang kaugnayan sa paksang pangungusap', 'Direktang sumuporta at magpaliwanag sa paksang pangungusap', 'Palaging tanong', 'Hindi kailangan sa isang talata', 'b'),
  (1, true, 4, NULL, 'Kapag sumusulat ng pangwakas na pangungusap, dapat itong', 'Bumuod sa pangunahing ideya ng talata', 'Magpakilala ng bagong paksa', 'Magtanong lamang', 'Walang kaugnayan sa nauna', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why early Filipino trading kingdoms had contact with Srivijaya and Majapahit despite the distance?', 'They traveled and traded by sea across the region', 'They had no way to travel at all', 'They only communicated through modern technology', 'They were part of the same landmass', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why the Philippines'' location along the Pacific Ring of Fire affects its geography?', 'It causes frequent volcanic and earthquake activity', 'It means the country has no mountains', 'It prevents any natural disasters', 'It has no effect on the landscape', 'a'),
  (1, true, 4, NULL, 'Which of these best explains the benefit of ASEAN countries maintaining friendly diplomatic relationships?', 'It helps prevent conflicts and encourages regional cooperation', 'It guarantees each country becomes wealthy overnight', 'It has no real effect on the countries involved', 'It forces all countries to have the same government', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why balancing economic activities like farming, fishing, and manufacturing is important for a country?', 'It creates a diverse economy that isn''t overly dependent on just one resource or industry', 'It has no real benefit to the country', 'It only benefits large corporations', 'It prevents any form of trade', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why understanding fact versus opinion is an important reading skill?', 'It helps readers evaluate information critically instead of accepting every claim as true', 'It has no real use in reading', 'It only matters for writing fiction', 'Facts and opinions are always the same thing', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why authors use figurative language like similes and metaphors?', 'To make writing more vivid, interesting, and memorable for readers', 'To confuse the reader on purpose', 'To make sentences shorter', 'To avoid using any descriptive words', 'a'),
  (1, true, 4, NULL, 'Which of these best explains the purpose of using complex sentences with subordinate clauses in writing?', 'To show a more detailed relationship between ideas, like cause and effect or time', 'To make writing harder to understand on purpose', 'To avoid using verbs', 'To remove all punctuation', 'a'),
  (1, true, 4, NULL, 'Which of these best explains the difference between active and passive voice?', 'In active voice, the subject does the action; in passive voice, the subject receives the action', 'There is no difference between them', 'Passive voice is always used in stories', 'Active voice always uses the word "by"', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why writers consider connotation, not just denotation, when choosing words?', 'Because words with similar meanings can carry different emotional feelings that affect the reader', 'Because connotation has no effect on meaning', 'Because denotation is always more important', 'Because word choice never matters in writing', 'a'),
  (1, true, 4, NULL, 'Alin sa mga sumusunod ang wastong ayos ng talata: paksang pangungusap, ______, at pangwakas na pangungusap?', 'Mga detalyeng sumusuporta', 'Panimula lamang', 'Bantas', 'Pamagat', 'a'),
  (1, true, 4, NULL, 'Bakit mahalaga ang paggamit ng tayutay sa pagsulat?', 'Nagpapaganda at nagpapalalim ito sa damdamin ng isinusulat', 'Nakakalito lamang ito sa mambabasa', 'Wala itong kabuluhan sa panitikan', 'Ginagamit lamang ito sa agham', 'a'),
  (1, true, 4, NULL, 'Bakit mahalagang malaman ang pagkakaiba ng uri ng teksto (salaysay, paglalarawan, nagbibigay-impormasyon, persuasibo)?', 'Upang maunawaan ng mambabasa ang layunin ng may-akda sa pagsulat', 'Upang mahirapan lamang ang mambabasa', 'Walang kabuluhan ang pagkakaiba nito', 'Para lamang sa guro', 'a'),
  (1, true, 4, NULL, 'In the sentence "The kitten''s fur felt like soft cotton," which figure of speech is used?', 'Simile', 'Metaphor', 'Personification', 'Onomatopoeia', 'a'),
  (1, true, 4, NULL, 'In the sentence "The old house groaned in the wind," which figure of speech is used?', 'Simile', 'Personification', 'Hyperbole', 'Metaphor only', 'b'),
  (1, true, 4, NULL, 'Which of these best describes why the Philippines is considered part of both the tropics and the Ring of Fire?', 'Its location near the equator brings warm weather, and its position along tectonic plate boundaries brings volcanic activity', 'It has no connection to either', 'It is located near the North Pole', 'It has no volcanoes or warm climate', 'a'),
  (1, true, 4, NULL, 'Which of these is the best example of using context clues to figure out a word''s meaning: "The famished dog quickly gobbled up its food."', 'Famished likely means very hungry', 'Famished likely means very full', 'Famished likely means sleepy', 'Famished likely means angry', 'a'),
  (1, true, 4, NULL, 'Which sentence correctly combines two ideas using a subordinate clause starting with "since"?', 'Since it was raining, the game was postponed.', 'Since it was raining the game, was postponed.', 'The game was postponed, since it, was raining.', 'Since, it was raining was postponed the game.', 'a'),
  (1, true, 4, NULL, 'Which of these best shows a Grade 4 student correctly identifying the main clause in "When the bell rang, the students lined up quickly"?', '"When the bell rang" is the main clause', '"The students lined up quickly" is the main clause', 'There is no main clause', 'Both parts are subordinate clauses', 'b'),
  (1, true, 4, NULL, 'Which of these best explains the water cycle process that happens right before rain falls?', 'Condensation, when water vapor cools and forms clouds', 'Evaporation, when liquid water rises', 'Erosion', 'Fossilization', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why animals in a food chain depend on producers?', 'Producers make the food energy that all other organisms in the chain eventually rely on', 'Producers eat all the consumers', 'Producers have no role in the food chain', 'Only decomposers depend on producers', 'a'),
  (1, true, 4, NULL, 'Which of these best describes why understanding forces like gravity and friction is useful in daily life?', 'It helps explain why objects fall, why cars need brakes, and why things stop moving', 'It has no real-world use', 'It only matters for scientists', 'Forces do not affect daily activities', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why a boat floats on water while a rock sinks?', 'Their different shapes and densities affect how they interact with water', 'All objects always float on water', 'All objects always sink in water', 'Weight has no effect on floating or sinking', 'a'),
  (1, true, 4, NULL, 'Kapag sumusulat ng maikling kwento, mahalaga bang malinaw ang tagpuan at tauhan?', 'Oo, dahil nakakatulong ito sa mambabasa na maintindihan ang kwento', 'Hindi mahalaga ang tagpuan at tauhan', 'Kailangan lamang ito sa tula', 'Hindi kailanman ginagamit sa maikling kwento', 'a'),
  (1, true, 4, NULL, 'Alin sa mga sumusunod ang halimbawa ng metapora?', 'Ang mundo ay entablado.', 'Kasing bilis ng kidlat.', 'Ngumiti ang buwan sa akin.', 'Umuungol ang hangin.', 'a'),
  (1, true, 4, NULL, 'Which of these best explains the importance of ASEAN''s cultural exchange programs among member countries?', 'They help build understanding and friendship between different Southeast Asian cultures', 'They erase all cultural differences between countries', 'They only benefit one country', 'They have no impact on relationships between nations', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why the Philippines exports agricultural products like bananas and pineapples?', 'Its tropical climate is well-suited for growing these crops in large quantities', 'It has no farmland at all', 'These crops cannot grow in the Philippines', 'Exporting has no economic benefit', 'a');